parameters.message:
=
{{
(() => {
  const consulta = $('When chat message received').first().json.chatInput || 'No disponible';
 const agente = $('AI Agent + Tool').first().json;

const respuesta = agente.output || 'Sin respuesta';

const pasos = agente.intermediateSteps || [];

  const escapar = (valor) => String(valor)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

  const formatear = (texto) => escapar(texto)
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g, '<br>');

  const herramientas = pasos
    .map(p => p.action?.tool || p.tool)
    .filter(Boolean);

  const herramientasUnicas = [...new Set(herramientas)];

  const auditoria = herramientasUnicas.length
    ? herramientasUnicas.map(escapar).join(', ')
    : 'Sin herramientas registradas en los pasos intermedios';

  return `
  <div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#243044;line-height:1.6;">

    <div style="background:#17365D;color:white;padding:22px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;color:white;">Auditoría del Agente Jurídico</h2>
      <p style="margin:6px 0 0;color:#E1EAF5;">Reporte automático de actividad</p>
    </div>

    <div style="padding:24px;border:1px solid #E1E5EB;">

      <p style="font-size:13px;color:#667085;">
        Fecha: ${$now.toFormat('dd/MM/yyyy HH:mm')}
      </p>

      <h3 style="color:#17365D;">Consulta recibida</h3>
      <div style="background:#F2F5FA;padding:14px;border-radius:6px;">
        ${formatear(consulta)}
      </div>

      <h3 style="color:#17365D;margin-top:26px;">Herramientas utilizadas</h3>
      <p>${auditoria}</p>

      <h3 style="color:#17365D;margin-top:26px;">Respuesta del agente</h3>
      <div style="padding:14px;border-left:3px solid #3273B9;background:#FAFBFD;">
        ${formatear(respuesta)}
      </div>

    </div>

    <div style="font-size:12px;color:#667085;text-align:center;padding:15px;">
      Reporte generado automáticamente mediante n8n
    </div>

  </div>`;
})()
}}
